define([],function(){'use strict';function openLTProfile(uid,gid){var modal=document.getElementById('lt-modal');var frame=document.getElementById('lt-modal-frame');if(!modal||!frame){return;}frame.src=M.cfg.wwwroot+'/local/learnpath/profile.php?userid='+uid+'&groupid='+gid;modal.classList.add('visible');document.body.style.overflow='hidden';}function closeLTModal(){var modal=document.getElementById('lt-modal');var frame=document.getElementById('lt-modal-frame');if(!modal||!frame){return;}modal.classList.remove('visible');frame.src='';document.body.style.overflow='';}function ltSortTable(tableId,colIdx,thEl){var table=document.getElementById(tableId);if(!table){return;}var tbody=table.tBodies[0];var rows=Array.from(tbody.rows);var asc=thEl.dataset.sortDir!=='asc';thEl.dataset.sortDir=asc?'asc':'desc';table.querySelectorAll('.lt-sort-arrow').forEach(function(a){a.textContent='⇅';});thEl.querySelector('.lt-sort-arrow').textContent=asc?'↑':'↓';rows.sort(function(a,b){var av=a.cells[colIdx]?a.cells[colIdx].innerText.trim():'';var bv=b.cells[colIdx]?b.cells[colIdx].innerText.trim():'';var an=parseFloat(av.replace('%',''));var bn=parseFloat(bv.replace('%',''));var cmp=(!isNaN(an)&&!isNaN(bn))?(an-bn):av.localeCompare(bv);return asc?cmp:-cmp;});rows.forEach(function(r){tbody.appendChild(r);});}function ltFilterTable(q){q=(q||'').toLowerCase().trim();document.querySelectorAll('#lt-summary-table .lt-learner-row').forEach(function(row){var name=row.getAttribute('data-name')||'';var email=row.getAttribute('data-email')||'';row.style.display=(!q||name.includes(q)||email.includes(q))?'':'none';});}function ltCountSelected(){var checked=new Set();document.querySelectorAll('.lt-row-check:checked').forEach(function(cb){checked.add(cb.value);});var n=checked.size;var el=document.getElementById('lt-bulk-count');if(el){el.textContent=n>0?n+' selected':'';}var sa=document.getElementById('lt-select-all');if(sa){var allVals=new Set();document.querySelectorAll('.lt-row-check').forEach(function(cb){allVals.add(cb.value);});sa.indeterminate=n>0&&n<allVals.size;sa.checked=allVals.size>0&&n===allVals.size;}}function ltToggleAll(checked){document.querySelectorAll('.lt-row-check').forEach(function(cb){if(cb.closest('tr').style.display!=='none'){cb.checked=checked;}});ltCountSelected();}function ltBulkAction(action){var idSet=new Set();document.querySelectorAll('.lt-row-check:checked').forEach(function(cb){idSet.add(cb.value);});var ids=Array.from(idSet);if(ids.length===0){window.alert('Please select at least one learner.');return;}var params=new URLSearchParams(window.location.search);var gid=params.get('groupid')||'0';if(action==='remind'){if(!window.confirm('Send a reminder to '+ids.length+' learner(s)?')){return;}submitHiddenForm(M.cfg.wwwroot+'/local/learnpath/reminders.php',{groupid:gid,action:'bulk_remind',userids:ids.join(','),sesskey:M.cfg.sesskey});}else if(action==='enroll'){if(!window.confirm('Enrol '+ids.length+' selected learner(s) in all missing courses?')){return;}submitHiddenForm(M.cfg.wwwroot+'/local/learnpath/index.php',{groupid:gid,view:'summary',bulk_enroll:1,sesskey:M.cfg.sesskey,userids:ids.join(',')});}}function submitHiddenForm(action,fields){var form=document.createElement('form');form.method='post';form.action=action;Object.keys(fields).forEach(function(k){var fi=document.createElement('input');fi.type='hidden';fi.name=k;fi.value=fields[k];form.appendChild(fi);});document.body.appendChild(form);form.submit();}function initModalClose(){document.addEventListener('keydown',function(e){if(e.key==='Escape'){closeLTModal();}});var overlay=document.getElementById('lt-modal');if(overlay){overlay.addEventListener('click',function(e){if(e.target===overlay){closeLTModal();}});}}function initSearch(){var input=document.getElementById('lt-search-input');if(input){input.addEventListener('input',function(){ltFilterTable(input.value);});}}return{init:function(){window.openLTProfile=openLTProfile;window.closeLTModal=closeLTModal;window.ltSortTable=ltSortTable;window.ltFilterTable=ltFilterTable;window.ltToggleAll=ltToggleAll;window.ltCountSelected=ltCountSelected;window.ltBulkAction=ltBulkAction;initModalClose();initSearch();}};});
